return ['domain'=>NULL,'plural-forms'=>'nplurals=1; plural=0;','language'=>'dzo','project-id-version'=>'Babilim 1.2.2','pot-creation-date'=>'2026-11-09T07:54:09+00:00','po-revision-date'=>'2026-11-09T07:54:09+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'ཁྱེད་ཀྱིས་ Babilim ལག་ལེན་འཐབ་ཤིག་ཚུ་ཨེབ་པའི་སྐབས་དང་ ས་ཁོངས་འདི་བསྐྱར་དུ་ཐོ་བཀོད་འབད་དགོ་པ་ཅིན་ ཡང་བསྐྱར་གཏང་ཡོད། ཁྱེད་ཀྱི་ས་ཁོངས་ཀྱི་ URL, WordPress དང་ PHP, Babilim ཚུ་གི་ཐོན་རིམ་ ཁྱེད་ཀྱི་ས་ཁོངས་ཀྱི་སྐད་ཡིག་དང་ དེ་ནང་ལག་ལེན་འཐབ་བཞིན་པའི་སྐད་ཡིག་ཚུ་ ད་ལས་ས་ཁོངས་འདི་གི་དོན་ལུ་བཟོ་ཡོད་པའི་སྤྱི་སྤྱོད་ལྡེ་མིག་ཅིག་ཨིན།','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'ཞིབ་དཔྱད་རེ་རེ་བཞིན་དུ་གཏང་ཡོད་མི་འདི་ནི། གཞི་བཙུགས་འབད་ཡོད་པའི་པླ་གིན་དང་བརྗོད་དོན་ཚུ་གི་ཐོ་ཡིག དེ་ཚུ་གི་དོན་ལུ་གཞི་བཙུགས་འབད་ཡོད་པའི་ Babilim ཡིག་སྒྱུར་ཚུ་གི་གནས་སྟངས་ ལག་ལེན་འཐབ་བཞིན་པའི་སྐད་ཡིག་ཚུ་ དང་ ཉེས་དཔྱད་ཀོཌ་ཐུང་ཀུ་ཚུ་ཨིན།','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'ཞུ་བ་རེ་རེ་ནང་ཁྱེད་ཀྱི་ས་ཁོངས་ཀྱི་ URL འདུག ད་ལས་ཞབས་ཏོག་གིས་དགོ་པའི་སྐབས་རྡོག་རེ་ལུ་ས་ཁོངས་ཀྱི་འཛུལ་སྤྱོད་ཊོ་ཀེན་ཡང་ཚུད་དེ་འདུག','What Babilim sends to the service'=>'Babilim གིས་ཞབས་ཏོག་ལུ་གཏང་མི་ཚུ','Your site\'s URL'=>'ཁྱེད་ཀྱི་ས་ཁོངས་ཀྱི་ URL','WordPress version'=>'WordPress ཐོན་རིམ།','PHP version'=>'PHP ཐོན་རིམ།','Babilim version'=>'Babilim ཐོན་རིམ།','Your site\'s language'=>'ཁྱེད་ཀྱི་ས་ཁོངས་ཀྱི་སྐད་ཡིག','Languages in use on your site'=>'ཁྱེད་ཀྱི་ས་ཁོངས་ནང་ལག་ལེན་འཐབ་བཞིན་པའི་སྐད་ཡིག','A public key for this site'=>'ས་ཁོངས་འདི་གི་སྤྱི་སྤྱོད་ལྡེ་མིག','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'ས་ཁོངས་འདི་གི་དོན་ལུ་བཟོ་ཡོད་པའི་སྤྱི་སྤྱོད་ལྡེ་མིག་ཅིག་ཨིན། ཞུ་བ་ཚུ་ཐད་ཀར་ས་ཁོངས་འདི་ལས་འབྱུང་མི་ཨིན་པའི་བདེན་ཁུངས་སྐྱེལ་ནིའི་དོན་ལུ་ལག་ལེན་འཐབ་ཨིན། སྤྱི་སྤྱོད་ཀྱི་ཆ་ཤས་རྐྱངམ་ཅིག་གཏང་ཨིན། སྒེར་གྱི་ཆ་ཤས་འདི་ཁྱེད་ཀྱི་ས་ཁོངས་ནང་སྡོད་ཨིན།','Installed plugins and themes'=>'གཞི་བཙུགས་འབད་ཡོད་པའི་པླ་གིན་དང་བརྗོད་དོན།','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'གཞི་བཙུགས་འབད་ཡོད་པའི་པླུ་གིན་དང་ཐིམ་རེ་རེའི་དོན་ལུ། མིང་ (slug)། ཐོན་རིམ། text domain། WordPress.org ནང་ཐོ་བཀོད་འབད་ཡོདཔ་ཨིན་མེན། དེ་ལས་ དེ་ནང་ཧེ་མ་ལས་ཚུད་ཡོད་པའི་སྐད་ཡིག་ཚུ། ཁྱེད་ཀྱིས་གཞི་བཙུགས་འབད་ཡོད་པའི་ Babilim ཡིག་སྒྱུར་རེ་རེའི་དོན་ལུ། ཐོན་རིམ་གང་ཨིན་ན། མཐའ་མར་ཞིབ་དཔྱད་འབད་ཡོད་པའི་ཚེས་གྲངས། དེ་ལས་ ཡིག་ཆ་ཞིབ་དཔྱད་འདི་ལས་ཐར་ཡོདཔ་ཨིན་མེན།','Source files (only if you confirm an upload)'=>'འབྱུང་ཁུངས་ཡིག་ཆ། (ཁྱེད་ཀྱིས་ཡར་སྤྲོད་གུ་ངེས་འཛིན་འབད་པ་ཅིན་རྐྱངམ་ཅིག)','Diagnostic codes'=>'ཉེས་དཔྱད་ཀོཌ།','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'ཉེས་དཔྱད་ཀོཌ་ཐུང་ཀུ་༢༠ ཚུན་ (དཔེར་ན། ཞིབ་དཔྱད་འབད་བའི་སྐབས་འཐུས་ཤོར་བའི་ཡིག་སྒྱུར་ཡིག་ཆ) རེ་རེ་ནང་པླ་གིན་ཡང་ན་བརྗོད་དོན། སྐད་ཡིག་དང་བྱུང་བའི་དུས་ཚོད་ཚུད་དེ་འདུག དེ་ཚུ་ནང་ཁྱེད་ཀྱི་ས་ཁོངས་ཀྱི་ཚིག་ཡིག་ ཡང་ན་ཡིག་སྒྱུར་འབད་ཡོད་པའི་ཚིག་ཡིག་ཅི་ཡང་ནམ་ཡང་མི་ཚུད།','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'དྲ་བསྒྲིགས་འདི་ནང་ ཝེབ་ས་ཁ་ %1$d གིས་ པླག་ཨིན་བསུབ་པའི་སྐབས་ Babilim ངོ་རྟགས་བསུབ་གཏང་ནིའི་ གཞི་སྒྲིག་འབད་ཡོད། ཝེབ་ས་ཁ་ཚུ་ལུ་མཚམས་སྦྱར་ཡོད་པའི་འཐུས་ཀྱི་ཆོག་ཐམ་འདི་ རང་བཞིན་གྱིས་སླར་གསོ་འབད་མི་ཚུགས། %2$s ལུ་ Babilim རྒྱབ་སྐྱོར་ལུ་འབྲེལ་བ་འཐབ་དགོ། ངོ་རྟགས་སྲུང་ནིའི་དོན་ལུ་ "ཆ་མེད་" ལུ་ཨེབ་ཞིནམ་ལས་ ཝེབ་ས་ཁ་རེ་རེའི་ Babilim སྒྲིག་བཀོད་ནང་ "སྒྲིག་འཇུག་མེདཔ་བཟོཝ་འི་སྐབས་ Babilim གྱི་གནས་སྡུད་ཆ་མཉམ་ བསུབ་གཏང་" གི་རྟགས་བསུབ་སྟེ་ པླག་ཨིན་འདི་ ལོག་ལག་ལེན་མེད་བཟོ། དེ་ལས་ཀྱང་ ལག་ལེན་མེད་བཟོ་ནི་ཨིན་ན?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s འབད་ནི་ག་ཅི་ཡང་མིན་འདུག','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s། སྐད་ཡིག་འདམ་ཁ་རྐྱབ།','%d failed'=>'%d ཕམ་ཡི','%d not yet tried'=>'%d ད་ལྟོ་ཚུན་མ་བརྟག','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'སྙན་ཞུ་ %d བསྒུག་སྟེ་ཡོད། "Always share" དང་ "Don\'t share" འདི་ སྙན་ཞུ་དེ་ཚུ་ཆ་མཉམ་ལུ་ འཇུགཔ་ཨིན།','%d skipped'=>'%d མ་འབད་བར་ལྷག་སྐྱེལ་འབད་ཡི','%d succeeded'=>'%d མཐར་འཁྱོལ་ཡི','%d to install'=>'%d གཞི་བཙུགས་འབད་ནི།','(a public key generated for this site)'=>'(དྲ་ཚིགས་འདིའི་དོན་ལུ་བཟོ་མི་སྤྱི་འདོན་ལྡེ་མིག)','(detected)'=>'(ཤེས་རྟོགས་འབད་ཡོད)','(generic codes and coordinates only)'=>'(སྤྱིར་བཏང་གི་ཨང་རྟགས་དང་ས་གནས་ཀྱི་ཁ་གསལ་རྐྱངམ་ཅིག)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s ལུ་ གཙང་བཟོ་འབད་བའི་ལས་རིམ་ཅིག་ གནས་སྐབས་ཅིག་བཀག་བཞག་ནུག: %2$s། ཅི་ཡང་བསུབས་མི་འདུག།','A file in the component could not be read, so it was not packaged.'=>'ཆ་ཤས་ཀྱི་ནང་གི་ཡིག་ཆ་ཅིག་ལྷག་མ་ཚུགསཔ་ལས་ ཐུམ་སྒྲིལ་མ་འབད།','A host that serves only one PHP request at a time cannot complete this step.'=>'PHP ཞུ་བ་ཚར་གཅིག་ལུ་གཅིག་རྐྱངམ་ཅིག་ཞབས་ཏོག་འབད་མི་ཧོསཊི་གིས་གོམ་པ་འདི་མཇུག་བསྡུ་མི་ཚུགས།','A part of the upload kept failing, so the upload was cancelled.'=>'ཡར་སྐྱེལ་གྱི་ཆ་ཤས་ཅིག་ ལོག་ལོག་འཐུས་ཤོར་བས་ ཡར་སྐྱེལ་འདི་ ཆ་མེད་བཟོ་ཡི།','A translation cannot be requested for that locale on this site right now.'=>'ད་ལྟོ་ཝེབ་ས་ཁ་འདི་ནང་ སྐད་ཡིག་ས་ཁོངས་དེ་གི་དོན་ལུ་ ཡིག་སྒྱུར་ཞུ་མི་ཚུགས།','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'%1$s ལུ་ ཡིག་སྒྱུར་གྱི་སྟོན་གྲངས་ (%2$s) ལུ་ ཡིག་འབྲི་འབད་མི་འདི་ ཞུ་བ་གཞན་ཅིག་དང་ འགལ་བ་བྱུང་སྟེ་ ལག་ལེན་མ་འཐབ་པས། ཐོན་རིམ་གསར་ཤོས་འདི་ བཞག་ཡོདཔ་ཨིན།','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s ལུ་ ཡིག་སྒྱུར་གྱི་སྟོན་གྲངས་ (%2$s) ལུ་ ཡིག་འབྲི་འབད་མི་འདི་ མ་མཇུག་བསྡུ་བར་ ལག་ལེན་མ་འཐབ་པས (%3$s)།','Account'=>'རྩིས་ཐོ','Add another language'=>'སྐད་ཡིག་གཞན་ཅིག་ཁ་སྐོང་འབད','Advanced'=>'མཐོ་རིམ་','All'=>'ཆ་མཉམ','All free-plan slots for this site are used'=>'ས་ཁོངས་འདི་གི་ཆེད་དུ་ཡོད་པའི་རིན་མེད་འཆར་གཞིའི་གནས་ཆ་ཚང་མ་ལག་ལེན་འཐབ་ཚར་ཡི།','All languages'=>'སྐད་ཡིག་ཆ་མཉམ','Already in WordPress core'=>'WordPress གི་ ནང་སྒྲིག་ནང་ཡོད་ཟིན་པ','Already installed.'=>'ཧེ་མ་ལས་གཞི་བཙུགས་འབད་ཡོད།','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'གཞི་བཙུགས་གཞན་ཅིག་འབད་བའི་སྒང་ཨིན། སྐར་མ་འགའ་ཅིག་གི་ཤུལ་ལས་ལོག་ཚོད་ལྟ་འབད།','Automatic installs'=>'རང་བཞིན་གྱི་གཞི་བཙུགས་ཚུ','Automatic installs are now off; turn them on again in the settings if you want them.'=>'རང་འགུལ་གྱི་སྒྲིག་བཙུགས་ད་ལྟོ་ཁ་བསྡམས་ཡོད། དགོ་པ་ཅིན་ སྒྲིག་བཀོད་ནང་ལོག་ཁ་ཕྱེ།','Available'=>'ཐོབ་ཚུགས་པ','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'ཐོབ་ཚུགསཔ་ཡོད་པའི་ཡིག་སྒྱུར་ཚུ་ ཨེབ་གཏོང་གཅིག་གིས་གཞི་བཙུགས་འབད་ཚུགས། ཡིག་སྒྱུར་མ་འདུག་པ་ཚུ་ཞུ་ཚུགས། རང་འགུལ་གཞི་བཙུགས་ཁ་ཕྱེ་ཡོད་པའི་སྐབས་ ཁྱོད་ཀྱིས་འཛིན་སྐྱོང་འབད་མི་སྐད་ཡིག་ཚུ་གི་དོན་ལུ་ ཞབས་ཏོག་གིས་ཐོབ་ཚུགསཔ་སྦེ་ཐོ་བཀོད་འབད་མི་ཡིག་སྒྱུར་ཚུ་ ཉིནམ་གཅིག་ལུ་ཕྱོགས་མཐུན་ལན་གཉིས་ཀྱི་སྐབས་ལུ་གཞི་བཙུགས་འབད་ཡོདཔ་ཨིན།','Available · %s'=>'ཐོབ་ཚུགས་པ། · %s','Babilim'=>'Babilim','Babilim Settings'=>'Babilim སྒྲིག་བཀོད','Babilim adds translations for every language checked here.'=>'Babilim གིས་འདི་ནང་རྟགས་བཀོད་ཡོད་པའི་སྐད་ཡིག་ག་ར་གྱི་དོན་ལུ་ཡིག་སྒྱུར་ཁ་སྐོང་འབདཝ་ཨིན།','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim གིས་ ཝེབ་ས་ཁོངས་ཀྱི་ཕྱི་ཁར་ གནས་སྐབས་ཀྱི་ཡིག་སྣོད་ཅིག་ངེས་གཏན་བཟོ་མ་ཚུགས་པའི་ཁར་ ཆ་ཤས་འདི་ཐུམ་སྒྲིལ་མ་འབད་བར་ ཡར་སྤེལ་ཡང་མ་འབད། wp-config.php ནང་ BABILIM_TEMP_DIR དེ་ ཝེབ་རྩ་བའི་ཕྱི་ཁར་ཡོད་པའི་ བྲིས་ཚུགས་པའི་ཡིག་སྣོད་ཅིག་སྦེ་ངེས་འཛིན་འབད། (དཔེར་ན་ ཁྱེད་རའི་ས་ཁོངས་ཀྱི་མི་མང་ཡིག་སྣོད་ཀྱི་ནང་མེན་པར་ དེའི་ཟུར་ན་ཡོད་པའི་ཡིག་སྣོད་ཅིག) ཡང་ན་ཁྱེད་ཀྱི་ཧོསིཊ་ལས་ཞུ།','Babilim could not finish checking this site.'=>'Babilim གིས་ ཝེབ་ས་ཚིགས་འདི་ཞིབ་དཔྱད་འབད་ཚར་མ་ཚུགས།','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim གིས་ལག་ལེན་འཐབ་ཏུ་བཙུགས་ནི་མཇུག་བསྡུ་མ་ཚུགས་ (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim གིས་དྲྭ་ས་ཁོངས་འདི་ངེས་དཔྱད་འབད་མ་ཚུགས། (ཞབས་ཏོག་གིས་ལོག་སྟེ་མཐུད་མ་ཚུགས།) ཐོ་བཀོད་མཚམས་འཇོག་འབད་ཡོད།','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim གིས་ ཝེབ་ས་ཚིགས་འདི་ངེས་དཔྱད་འབད་མ་ཚུགས་པས་ ངེས་དཔྱད་མ་འཐོབ་ཚུན་ ཕབ་ལེན་ཡང་ན་ གཞི་བཙུགས་ག་ནི་ཡང་མི་འབད།','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim གིས་ས་ཁོངས་འདི་ར་སྤྲོད་འབད་མ་ཚུགས་པའི་ཁར་ག་ཅི་ཡང་ཕབ་ལེན་ཡང་ན་སྒྲིག་བཙུགས་མ་འབད།','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim གིས་ཝེབ་སައིཊ་འདི་གུ་ཡོད་པའི་པླ་གིན་དང་ཐིམ་ཚུ་གི་ནང་ལས་ ཁྱོད་ཀྱི་སྐད་ཡིག་ནང་ཡིག་སྒྱུར་མེད་མི་ཚུ་གི་ཆེད་དུ་ Babilim ཞབས་ཏོག་ལས་ཡིག་སྒྱུར་ཚུ་ལེན་ཞིནམ་ལས་ ཁྱོད་ཀྱི་ཞབས་ཏོག་འཆར་གཞིའི་ནང་ཚུད་མི་ཚུ་ གཞི་བཙུགས་འབདཝ་ཨིན།','Babilim has not been enabled for this site yet.'=>'Babilim འདི་དྲ་ཚིགས་འདི་གི་དོན་ལུ་ད་ལྟོ་ཚུན་ཚོད་ལྕོགས་ཅན་མ་བཟོ།','Babilim has not installed any translation for this language.'=>'Babilim གིས་ སྐད་ཡིག་འདི་གི་དོན་ལུ་ ཁ་བསྒྱུར་གང་ཡང་ གཞི་མ་བཙུགསཔ་ཨིན།','Babilim hit an error. Share an error report?'=>'Babilim ལུ་ འཛོལ་བ་ཅིག་ བྱུང་སོང་། འཛོལ་བའི་སྙན་ཞུ་ བརྒྱུད་སྤྲོད་འབད་ནི་ཨིན་ན?','Babilim installed %d translation automatically since your last visit.'=>'ཁྱེད་ཀྱི་མཇུག་གི་ལྟ་སྐོར་ཤུལ་ལས་ Babilim གིས་ཡིག་སྒྱུར་ %d རང་འགུལ་གྱིས་སྒྲིག་བཙུགས་འབད་ཡོད།','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim ལག་ལེན་མེད་པར་བཞག་ཡོད། ད་ལས་ཕར་ག་ཅི་ཡང་མི་གཏང་། སྒྲིག་བཙུགས་འབད་ཚར་བའི་ཡིག་སྒྱུར་ཚུ་ལཱ་འབད་བཞགཔ་ཨིན།','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim ལག་ལེན་འཐབ་ཚུགསཔ་བཟོ་ཡོད: ཝེབ་ས་ཁ་འདི་ ངེས་དཔྱད་འབད་ཡོདཔ་དང་ ཆ་ཤས་ %d ཐོབ་ཅི།','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim རང་ གིས་ ལག་ལེན་འཐབ་ཚུགསཔ་བཟོ་སྟེ་ ཝེབ་ས་ཁ་འདི་ ཞིབ་དཔྱད་འབད་དེ་ཡོད། (མཇུག་གི་ཚོད་ལྟ་: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim གིས་དྲ་ཚིགས་འདི་ལག་ལེན་འཐབ་ཏུ་བཙུགས་ཞིན་ཏེ་ཞིབ་དཔྱད་འབད་དེ་ཡོད། ཤོག་ལེབ་འདི་བསྐྱར་མངོན་འབད་ ཡང་ན་ དུས་ཚོད་བཀོད་པའི་ཞིབ་དཔྱད་མཇུག་འཁྱོལ་ཚུན་སྒུག་གནང་།','Babilim is not enabled.'=>'Babilim འདི་ལྕོགས་ཅན་མ་བཟོ་བས།','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim གིས་ པླག་ཨིན་བསུབ་པའི་སྐབས་ ཝེབ་ས་ཁ་འདི་གི་ངོ་རྟགས་བསུབ་གཏང་ནིའི་ གཞི་སྒྲིག་འབད་ཡོད། ཝེབ་ས་ཁ་འདི་ལུ་མཚམས་སྦྱར་ཡོད་པའི་འཐུས་ཀྱི་ཆོག་ཐམ་འདི་ རང་བཞིན་གྱིས་སླར་གསོ་འབད་མི་ཚུགས། %s ལུ་ Babilim རྒྱབ་སྐྱོར་ལུ་འབྲེལ་བ་འཐབ་དགོ། ངོ་རྟགས་འདི་སྲུང་ནིའི་དོན་ལུ་ "ཆ་མེད་" ལུ་ཨེབ་ཞིནམ་ལས་ Babilim སྒྲིག་བཀོད་ནང་ "སྒྲིག་འཇུག་མེདཔ་བཟོཝ་འི་སྐབས་ Babilim གྱི་གནས་སྡུད་ཆ་མཉམ་ བསུབ་གཏང་" གི་རྟགས་བསུབ་སྟེ་ པླག་ཨིན་འདི་ ལོག་ལག་ལེན་མེད་བཟོ། དེ་ལས་ཀྱང་ ལག་ལེན་མེད་བཟོ་ནི་ཨིན་ན?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim གི་ཐབས་ཤེས་འདི་གི་ཆེད་དུ་ དུས་ཡུན་ཚང་སོང་ཞིནམ་ལས་ ཞིབ་དཔྱད་ཤུལ་མམ་ནང་མུ་མཐུད་འབད་འོང་།','Babilim settings'=>'Babilim སྒྲིག་བཀོད','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim གི་མཉམ་འགྲིག་འདི་ ཞབས་ཏོག་གིས་གནས་སྐབས་ཀྱི་དོན་ལུ་འགོར་འགྱངས་བཞག་ཡོད་ (ཞུ་བའི་ཚད་བཀག); %s གི་ཤུལ་ལས་ལོག་ཚོད་ལྟ་འབད་འོང་།','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'ཡར་སྤེལ་འདི་སྒུག་སྡོད་པའི་སྐབས་ Babilim དུས་མཐུན་བཟོ་ཡོད། ཐུམ་སྒྲིལ་རྒན་པ་འདི་བཏོན་ཡོད། ཡར་སྤེལ་འདི་ལོག་ངེས་གཏན་བཟོ་གནང་།','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim གིས་ %1$s (ཐོན་རིམ་ %2$s) ལས་ཡིག་སྣོད་འདི་ཚུ་ཡར་སྤེལ་འབད་འོང་། .php དང་ .js ཡིག་སྣོད་ཆ་མཉམ་ block.json ཡིག་སྣོད་ཆ་མཉམ་ དེ་ལས་གཙོ་བོའི་ཡིག་སྣོད་ནང་གི་ readme.txt, readme.md, style.css དང་ theme.json ཚུ་ཨིན། དེ་ཚུ་ ཡིག་སྒྱུར་འབད་དགོ་པའི་ཚིག་འཚོལ་ནིའི་དོན་ལུ་དང་ པླགིན་ཡང་ན་ བརྡ་མཚོན་དཔེ་རྣམ་ (theme) ངོས་འཛིན་འབད་ནིའི་དོན་ལུ་ལག་ལེན་འཐབ་ཨིན།','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest འདི་ལག་ལེན་འཐབ་མི་ཚུགས: %s','Back'=>'ལོག་ཤོག','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'ཁྱོད་ཀྱིས་ཧེ་མ་ཁྱབ་ཁོངས་འདི་གི་དོན་ལུ་ཆོག་མཆན་ཉོ་ཡོད་ག? དངུལ་སྤྲོད་པའི་སྐབས་ལུ་ཐོབ་མི་སླར་གསོ་ཀོཌ་འདི་བཙུགས།','Broken placeholder'=>'ཚབ་ཚིག་ཆད་ཅི','Build'=>'བཟོ་བསྐྲུན།','Built'=>'བཟོ་ཡོད','Bulk actions apply only to the selected language of each selected component.'=>'སྡེ་ཚན་གྱི་བྱ་བ་ཚུ་ སེལ་འཐུ་འབད་ཡོད་པའི་ཆ་ཤས་རེ་རེ་གི་ སེལ་འཐུ་འབད་ཡོད་པའི་སྐད་ཡིག་ལུ་རྐྱངམ་ཅིག་ ལག་ལེན་འཐབ་ཨིན།','Bulk actions apply to every matching language of each selected component.'=>'སྡེ་ཚན་གྱི་བྱ་བ་ཚུ་ སེལ་འཐུ་འབད་ཡོད་པའི་ཆ་ཤས་རེ་རེ་གི་ མཐུན་པའི་སྐད་ཡིག་ག་ར་ལུ་ ལག་ལེན་འཐབ་ཨིན།','Bulk download:'=>'ཚོགས་རྩིས་ཕབ་ལེན:','Bulk request:'=>'ཚོགས་རྩིས་ཞུ་བ:','Bulk update:'=>'ཚོགས་རྩིས་དུས་མཐུན:','Bundled with the plugin'=>'པླག་ཨིན་དང་ཅིག་ཁར་བསྡོམས་ཡོད།','Bundled with the theme'=>'ཐིམ་དང་ཅིག་ཁར་བསྡོམས་ཡོད།','By clicking Enable, you agree to send the information listed above to Babilim.'=>'"སྤྱོད་ཚུགས་བཟོ" (Enable) ལུ་ཨེབ་ཐོག་ཁྱེད་ཀྱིས་གོང་ལུ་ཁ་གསལ་བཀོད་པའི་ཆ་འཕྲིན་ Babilim ལུ་གཏོང་ནི་ལུ་ཆ་འཇོག་འབདཝ་ཨིན།','By continuing you confirm that you have the right to upload this component.'=>'འཕྲོ་མཐུད་པའི་ཐོག་ལས་ ཁྱོད་ལུ་ཆ་ཤས་འདི་ཡར་སྐྱེལ་འབད་ནིའི་ཐོབ་ཐང་ཡོདཔ་ངེས་འཛིན་འབདཝ་ཨིན།','Cancel'=>'ཆ་མེད་གཏང་།','Category'=>'སྡེ་ཚན།','Check again'=>'ལོག་ཞིབ་དཔྱད་འབད','Check again now'=>'ད་ལྟོ་ལོག་ཞིབ་དཔྱད་འབད','Checkout is not available for this site right now.'=>'ད་ལྟོ་ཝེབ་ས་ཁ་འདི་གི་དོན་ལུ་ འཐུས་སྤྲོད་(checkout) འཐོབ་མི་ཚུགས།','Choose'=>'སེལ་འཐུ་འབད།','Choose a category…'=>'སྡེ་ཚན་ཅིག་གདམ་ཁ་རྐྱབས…','Choose a language'=>'སྐད་ཡིག་ཅིག་འདམ་ཁ་རྐྱབ།','Choose a language…'=>'སྐད་ཡིག་ཅིག་འདེམ་སྒྲུག་འབད…','Clear filters'=>'ཚགས་མ་ཚུ་བསལ','Close'=>'ཁ་བསྡམས།','Component'=>'ཆ་ཤས།','Confirm'=>'ངེས་འཛིན།','Conflicting keys'=>'འགལ་བའི་ལྡེ་མིག','Continue'=>'འཕྲོ་མཐུད།','Continue next batch (%d left)'=>'ཤུལ་མམ་གྱི་ཚོགས་ཁག་ནང་འཕྲོ་མཐུད (%d ལྷག་ཡོད)','Continuing…'=>'འཕྲོ་མཐུད་དོ…','Could not back up %s before replacing it.'=>'%s ཚབ་བཙུགས་མ་འབད་བའི་ཧེ་མར་ གྲབས་ཁུངས་འདྲ་བཤུས་བཟོ་མ་ཚུགས།','Could not create the package archive.'=>'ཐུམ་སྒྲིལ་གྱི་ཡིག་མཛོད་བསྐྲུན་མ་ཚུགས།','Could not determine active components; the existing merged index was left unchanged.'=>'ལག་ལེན་ཅན་གྱི་ཆ་ཤས་ཚུ་ངོས་འཛིན་འབད་མ་ཚུགས། ཟླ་སྒྲིག་འབད་ཡོད་པའི་ཐོ་ཡིག་ཐོག་ལུ་འགྱུར་བ་མ་བཏང་བར་བཞག་ཅི།','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'གཞི་བཙུགས་འབད་ཡོད་པའི་ plugin/theme ཚུ་ ངོས་འཛིན་འབད་མ་ཚུགས། བསལ་གཏང་ནི་ འཕྱལ་བཞག་ཡོདཔ། ཅི་ཡང་བསུབས་མི་འདུག།','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'ཞབས་ཏོག་ལས་ WordPress.org གི་སྐད་ཡིག་ཐོ་ཡོངས་རྫོགས་མ་ཁུར་ཚུགས་པས་ ད་ལྟོ་སྐད་ཡིག་གཞན་ཅིག་ཁ་སྐོང་འབད་མི་ཚུགས།','Could not move %s into place.'=>'%s ས་གནས་ནང་བཙུགས་མ་ཚུགས།','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' གི་དོན་ལུ་ མཉམ་སྡེབ་འབད་ཡོད་པའི་ཟུར་ཐོ་འདི་ གནས་ཁར་བཤུད་མ་ཐུབ། ཧེ་མའི་ཟུར་ཐོ་ (ཡོད་པ་ཅིན) ཕྱེད་ཀ་རང་དུས་མཐུན་བཟོ་བཞག་མི་མེན་པར་ བསུབ་གཏང་ཡི། ཤུལ་མམ་གྱི་བསྐྱར་བཟོ་ལེགས་ཤོམ་མ་འབད་ཚུན་ སྐད་ཡིག་ས་ཁོངས་འདི་གི་དོན་ལུ་ སྔོན་སྒྲིག་ཁྱབ་ཁོངས་ཀྱི་ཁ་སྐོང་ བྱིན་མི་འོང་།','Could not open zip: %s'=>'zip ཁ་ཕྱེ་མ་ཚུགས: %s','Could not prepare %s for rollback.'=>'%s ཕྱིར་སློག་གི་དོན་ལུ་ གྲ་སྒྲིག་འབད་མ་ཐུབ།','Could not read %s back after moving it into place.'=>'%s ས་གནས་ནང་བཤུད་ཚརཝ་ཅིག་ལས་ ལོག་ལྷག་མ་ཐུབ།','Could not read: %s'=>'ལྷག་མ་ཚུགས: %s','Could not restore the purchase: %s'=>'ཉོ་སྒྲུབ་སླར་གསོ་འབད་མ་ཚུགས།: %s','Could not show a new restore code: %s'=>'སླར་གསོ་ཀོཌ་གསརཔ་སྟོན་མ་ཚུགས་: %s','Could not stage %s'=>'%s གྲ་སྒྲིག་འབད་མ་ཚུགས།','Could not stage default/%s'=>'default/%s གྲ་སྒྲིག་འབད་མ་ཚུགས།','Could not start checkout: %s'=>'འཐུས་སྤྲོད་(checkout) འགོ་བཙུགས་མ་ཚུགས་: %s','Could not verify entry count for %s'=>'%s གི་ཐོ་བཀོད་གྲངས་ཀ་ བདེན་དཔྱད་འབད་མ་ཚུགས།','Could not write the downloaded package to disk.'=>'ཕབ་ལེན་འབད་ཡོད་པའི་ཐུམ་སྒྲིལ་འདི་ཌིསིཀ་ལུ་འབྲི་མ་ཐུབ།','Could not write the staged merged index.'=>'རིམ་པ་བཞག་པའི་མཉམ་སྡེབ་སྟོན་གྲངས་འབྲི་མ་ཐུབ།','Current translation'=>'ད་ལྟོའི་ཡིག་སྒྱུར','Custom overrides'=>'རང་སྒྲིག་ཚབ་བཙུགས་ཚུ','Danger zone'=>'ཉེན་ཁའི་ས་ཁོངས','Default supplement entry count mismatch.'=>'སྔོན་སྒྲིག་ཁ་སྐོང་གི་ཐོ་བཀོད་གྲངས་ཀ་མཐུན་མ་སོང་།','Delete all Babilim data on uninstall'=>'སྒྲིག་འཇུག་མེདཔ་བཟོ་བའི་སྐབས་ Babilim གྱི་གནས་སྡུད་ཆ་མཉམ་ བསུབ་གཏང་','Disable Babilim'=>'Babilim ལག་ལེན་འཐབ་ནི་བཀག','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim ལག་ལེན་མི་འཐབ་ནི་ཨིན་ན། སྒྲིག་བཙུགས་འབད་ཡོད་པའི་ཡིག་སྒྱུར་ཚུ་བསྐྱངས་ཡོདཔ་ད་ ད་ལས་ཕར་ཁ་ཞིབ་དང་ཕབ་ལེན་མི་འབད།','Don\'t share'=>'Don\'t share','Download'=>'ཕབ་ལེན','Downloaded and installed.'=>'ཕབ་ལེན་དང་གཞི་བཙུགས་འབད་ཚར་ཡི།','Downloading…'=>'ཕབ་ལེན་འབད་དོ…','Downloads: %1$d/%2$d (%3$s)'=>'ཕབ་ལེན་: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ཆ་ཤས་རེ་རེ་གིས་ སྐད་ཡིག་ས་ཁོངས་རེ་རེའི་མཉམ་སྤྱོད་སྔོན་སྒྲིག་ཁྱབ་ཁོངས་ཀྱི་ཁ་སྐོང་ནང་བཙུགས་མི་རང་གི་ཞལ་འདེབས།','Enable Babilim'=>'Babilim ལག་ལེན་འཐབ་ཚུགསཔ་བཟོ','Enabling…'=>'ལག་ལེན་འཐབ་ཚུགསཔ་བཟོ་དོ…','English (United States)'=>'English (United States)','Entries'=>'ཐོ་བཀོད་ཚུ','Entry count mismatch for %s'=>'%s གི་དོན་ལུ་ ཐོ་བཀོད་གྲངས་ཀ་མཐུན་མ་སོང་།','Error reports'=>'འཛོལ་བའི་སྙན་ཞུ།','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'དྲ་སྟོན་འདི་ལུ་ ལག་ལེན་འཐབ་ཡོད་པའི་ ས་ཁོངས་སྐད་ཡིག་ག་ར་ (དྲ་སྟོན་གྱི་ས་ཁོངས་སྐད་ཡིག་ གཞི་བཙུགས་འབད་ཡོད་པའི་ སྐད་ཡིག་ཐུམ་སྒྲིལ་ ལག་ལེན་པའི་ས་ཁོངས་སྐད་ཡིག་ དང་ ཁྱོད་ཀྱིས་ ལགཔ་གིས་ཁ་སྣོན་འབད་མི་ གང་རུང་)། ས་ཁོངས་སྐད་ཡིག་ཅིག་ གཞན་ལས་ ཁྱད་པར་མེད།','Excluded'=>'བཀག་བཞག་ཡོདཔ','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'མིང་ཡང་ན་རྒྱ་བསྐྱེད་གཞན་ཡོད་པའི་ཡིག་སྣོད་ཚུ་ཚུད་མི་འདུག དེ་བཟུམ་ད་ uploads, cache, logs, backup, data, vendor, node_modules དང་ languages ཡིག་སྣོད་ཚུ་དང་ གབ་ཡོད་པའི་ཡིག་སྣོད་ཚུ་ དེ་ལས་མིང་དེ་ གསང་བའི་དངོས་པོ་དང་མཚུངས་པའི་ཡིག་སྣོད་ཚུ་ (wp-config*, .env*, *.sql, *.log, *.pem, *.key) ཡང་ཚུད་མི་འདུག ཀོཌ་ཡིག་སྣོད་ཚུ་ནང་ ཁྱེད་ཀྱིས་མཉམ་སྤྱོད་མ་འབད་འདོད་པའི་ཚིག་ཡང་ན་ data ཡོད་སྲིད། ངེས་མེད་པ་ཅིན་ ཞིབ་འཇུག་འབད། ཞབས་ཏོག་གིས་ ཡིག་སྣོད་ཚུ་འབྱོར་བའི་སྐབས་ ཡིག་སྣོད་དེ་བཟུམ་ཚུ་ཕྱིར་ལོག་སེལ་ཨིན།','Fills in missing translations for the plugins and themes already installed on your site.'=>'ཁྱོད་ཀྱི་དྲ་ཚིགས་ནང་ཚུད་ཡོད་པའི་ plugins དང་ themes ཚུ་གི་ཆེད་དུ་ མ་ཚང་བའི་ Translations བཀང་སྟེ་བྱིནམ་ཨིན།','Free'=>'རིན་མ་དགོ','Free-plan slots'=>'རིན་མེད་འཆར་གཞིའི་གནས་ཆ','General'=>'སྤྱིར་བཏང་','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'འདི་ཁ་ཕྱེ་ཡོད་པ་ཅིན་ སྒྲིག་འཇུག་མེདཔ་བཟོཝ་ད་ ཝེབ་ས་ཁ་འདི་གི་ངོ་རྟགས་ཡང་ བསུབ་གཏངམ་ཨིན། ཝེབ་ས་ཁ་འདི་ལུ་མཚམས་སྦྱར་ཡོད་པའི་འཐུས་ཀྱི་ཆོག་ཐམ་འདི་ ཤུལ་ལས་རང་བཞིན་གྱིས་སླར་གསོ་འབད་མི་ཚུགས། ལོག་ཐོབ་ནིའི་དོན་ལུ་ %s ལུ་ Babilim རྒྱབ་སྐྱོར་ལུ་འབྲེལ་བ་འཐབ་དགོ།','Included'=>'ཚུད་ཡོད','Included in index'=>'སྟོན་གྲངས་ནང་ཚུདཔ་','Install available translations automatically'=>'ཐོབ་ཚུགསཔ་ཡོད་པའི་ཡིག་སྒྱུར་ཚུ་རང་བཞིན་གྱིས་གཞི་བཙུགས་འབད','Installed'=>'གཞི་བཙུགས་ཟིན།','Installed translations are kept, but no further checks or downloads will run.'=>'སྒྲིག་བཙུགས་འབད་ཡོད་པའི་ཡིག་སྒྱུར་ཚུ་བསྐྱངས་ཡོདཔ་ད་ ད་ལས་ཕར་ཁ་ཞིབ་དང་ཕབ་ལེན་མི་འབད།','Installed · %s'=>'གཞི་བཙུགས་ཟིན། · %s','Installed · built for %1$s, this site has %2$s'=>'གཞི་བཙུགས་འབད་ཡི། · %1$s གི་དོན་ལུ་བཟོ་ཡི། ཝེབ་ས་ཁ་འདི་ལུ་ %2$s ཡོད།','Installed · built for %s'=>'གཞི་བཙུགས་འབད་ཡི། · %s གི་དོན་ལུ་བཟོ་ཡི།','Installed · built for %s, new version failed'=>'གཞི་བཙུགས་འབད་ཡི། · %s གི་དོན་ལུ་བཟོ་ཡི། པར་གཞི་གསརཔ་འཐུས་ཤོར་བྱུང་ཡི།','Installed · built for %s, new version scheduled'=>'གཞི་བཙུགས་འབད་ཡོདཔ · %s གི་དོན་ལུ་བཟོ་ཡོདཔ། ཐོན་རིམ་གསརཔ་དུས་བཀོད་འབད་ཡོདཔ།','Installed · built for %s, translating the new version…'=>'གཞི་བཙུགས་འབད་ཡི། · %s གི་དོན་ལུ་བཟོ་ཡི། པར་གཞི་གསརཔ་ཡིག་སྒྱུར་འབད་བའི་སྒང་ཡོད…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'གཞི་བཙུགས་འབད་ཡོད · %s གི་དོན་ལུ་བཟོ་ཡོད། ཁ་སྣོན་ (plugin) ཡང་ན་ བརྗོད་གཞི་ (theme) འདི་ད་ལྟོ་དྲ་ཚིགས་ཀྱི་ཞབས་ཏོག་འཆར་གཞི་ནང་ཁྱབ་ཚུད་མེདཔ་ཨིན།','Installed · built for a different version'=>'གཞི་བཙུགས་འབད་ཡི། · པར་གཞི་གཞན་ཅིག་གི་དོན་ལུ་བཟོ་ཡི།','Installed · built for a different version, new version failed'=>'གཞི་བཙུགས་འབད་ཡི། · པར་གཞི་གཞན་ཅིག་གི་དོན་ལུ་བཟོ་ཡི། པར་གཞི་གསརཔ་འཐུས་ཤོར་བྱུང་ཡི།','Installed · built for a different version, new version scheduled'=>'གཞི་བཙུགས་འབད་ཡོདཔ · ཐོན་རིམ་གཞན་ཅིག་གི་དོན་ལུ་བཟོ་ཡོདཔ། ཐོན་རིམ་གསརཔ་དུས་བཀོད་འབད་ཡོདཔ།','Installed · built for a different version, translating the new version…'=>'གཞི་བཙུགས་འབད་ཡི། · པར་གཞི་གཞན་ཅིག་གི་དོན་ལུ་བཟོ་ཡི། པར་གཞི་གསརཔ་ཡིག་སྒྱུར་འབད་བའི་སྒང་ཡོད…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'གཞི་བཙུགས་འབད་ཡོད · ཐོན་རིམ་མ་འདྲཝ་ཅིག་གི་དོན་ལུ་བཟོ་ཡོད། ཁ་སྣོན་ (plugin) ཡང་ན་ གནས་སྟངས་བརྗོད་གཞི་ (theme) འདི་ད་ལྟོ་དྲ་ཚིགས་ཀྱི་ཞབས་ཏོག་འཆར་གཞི་ནང་ཁྱབ་ཚུད་མེདཔ་ཨིན།','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'འདི་ ཞབས་ཏོག་གི་ཧོསྟིང་མཁོ་སྤྲོད་པས་ཉར་ཚགས་འབད་ཞིནམ་ལས་ ཡིག་སྒྱུར་བཟོ་ནི་ལུ་ AI དཔེ་དབྱིབས་ཚུགིས་ལས་སྦྱོར་འབདཝ་ཨིན།','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'ཚང་མ་གཙང་བཟོ་འབད་བའི་སྐབས་དང་ པླག་ཨིན་འདི་བསུབ་པའི་སྐབས་ ངེའི་རང་གི་ཡིག་སྒྱུར་ཚབ་བཙུགས་ཚུ་བསྐྱངས་དགོ།','Language'=>'སྐད་ཡིག','Language:'=>'སྐད་ཡིག:','Languages'=>'སྐད་ཡིག་ཚུ','Languages found on this site: %s.'=>'ས་ཁོངས་འདི་ནང་སྐད་ཡིག་ཐོབ་ཡོད་མི་: %s།','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'%1$s ལུ་ མཐའ་མའི་གཙང་བཟོ: %2$d གསརཔ་རྟགས་བཀོད་འབད་ཡོདཔ། ཡིག་ཆ་ %3$d བསུབས་ཡོདཔ། དྲན་ཐོ་ %4$d རྩ་བསྐྲད་འབད་ཡོདཔ།','Maintenance'=>'ཉམས་གསོ།','Maintenance status is not available right now.'=>'ཉམས་གསོའི་གནས་སྟངས་འདི་ད་ལྟོ་མི་འཐོབ།','Manifest unavailable: %s'=>'མེནི་ཕེསཊ་ མཇལ་ཐབས་མེད: %s','Negation reversed'=>'ཁས་ལེན་དང་ཁས་མི་ལེན་ལོག་སྤྱོད་འབད་ཡོདཔ།','No'=>'མིན','No build is available to download for this locale.'=>'སྐད་ཡིག་ས་ཁོངས་འདི་གི་དོན་ལུ་ཕབ་ལེན་འབད་ནིའི་བཟོ་བསྐྲུན་མིན་འདུག','No cleanup has run yet.'=>'གཙང་བཟོ་ཅིག་ད་ལྟོ་ཚུན་ མ་གཡོག་བཀོལ་བས།','No components match these filters. %s'=>'ཆ་ཤས་ཅིག་ཀྱང་ཚགས་མ་འདི་ཚུ་དང་མཐུན་མ་སོང་། %s','No components synced yet.'=>'ཆ་ཤས་ག་ཅི་ཡང་ད་ལྟོ་ཚུན་མཉམ་བསྒྲིག་མ་འབད་བས།','No installed translation matches.'=>'གཞི་བཙུགས་འབད་ཡོད་པའི་ཁ་བསྒྱུར་གང་ཡང་ མཐུན་མི་འདུག','No language is managed yet.'=>'ད་ལྟོ་ཚུན་སྐད་ཡིག་ཅིག་ཡང་འཛིན་སྐྱོང་མ་འབད་བས།','No pending challenge for this nonce.'=>'nonce འདི་གི་དོན་ལུ་ བསྒུག་སྡོད་པའི་ཞིབ་དཔྱད་ལྡེ་མིག (challenge) མེདཔ་ཨིན།','No pending challenge to verify.'=>'ངེས་དཔྱད་འབད་ནིའི་ཞིབ་དཔྱད་ལྡེ་མིག (challenge) སྒུག་མི་མིན་འདུག','No plugins or themes found.'=>'པ་ལུ་གིན་ ཡང་ན་ ཐིམ་མ་ཐོབ།','No previous build to roll back to.'=>'ཕྱིར་སློག་འབད་ནིའི་དོན་ལུ་ ཧེ་མའི་བཟོ་བསྐྲུན་མེད།','No record for %s'=>'%s གི་དོན་ལུ་ཐོ་བཀོད་མེད།','No site id is on file to rotate a token for.'=>'ཊོཀ་ཀེན་བསྒྱུར་ནིའི་དོན་ལུ་ ཐོ་བཀོད་འབད་ཡོད་པའི་དྲྭ་ས་ཁོངས་ཀྱི་ id མིན་འདུག','No — component inactive'=>'མིན — ཆ་ཤས་འདི་ལག་ལེན་མི་འཐབ་པས','No — component removed'=>'མིན — ཆ་ཤས་འདི་རྩ་བསྐྲད་འབད་ཡོད','No — installed version differs from the active one'=>'མིན — སྒྲིག་བཙུགས་འབད་ཡོད་པའི་ཐོན་རིམ་འདི་ལག་ལེན་འཐབ་མི་དང་མ་མཐུན་པས','Not a valid server_build_id: %s'=>'server_build_id ནུས་ཅན་མེན: %s','Not covered by the free service plan'=>'རིན་མེད་ཞབས་ཏོག་འཆར་གཞིའི་ནང་ མ་ཚུདཔ།','Not installed'=>'གཞི་བཙུགས་མ་འབད་བས།','Not registered yet'=>'ད་ལྟོ་ཐོ་བཀོད་མ་འབད་བས','Not supported'=>'རྒྱབ་སྐྱོར་མིན་འདུག','Not verified'=>'ངེས་དཔྱད་མ་འབད་བས','Note (optional)'=>'དྲན་ཐོ་ (འདོད་ན།)','Nothing to choose.'=>'འདམ་ནིའི་ཅི་ཡང་མིན་འདུག','Nothing to confirm.'=>'ངེས་འཛིན་འབད་ནིའི་ཅི་ཡང་མིན་འདུག','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'སྔོན་སྒྲིག་ལུ་ཁ་བསྡམས་ཡོད། པླག་ཨིན་བསུབ་པ་ཅིན་ ས་ཁོངས་འདིའི་ངོ་རྟགས་བསྐྱངས་སྟེ་ཡོདཔ་ལས་ སླར་གཞི་བཙུགས་འབད་པ་ད་ ལོག་ལག་ལེན་འཐབ་ཚུགས།','One or more served files no longer match the manifest.'=>'བཀྲམ་སྤེལ་འབད་ཡོད་པའི་ཡིག་ཆ་གཅིག་ཡང་ན་ དེ་ལས་མང་མི་ཅིག་ ད་ལས་ཕར་ མེནི་ཕེསཊ་དང་མི་མཐུན་པར་ཡོད།','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'ཝེབ་སཱའིཊ་འདི་གི་དོན་ལུ་ཚར་གཅིག་གི་ཉོ་སྒྲུབ་: %1$s %2$s། མ་འོངས་པའི་ཡིག་སྒྱུར་གསར་བཅོས་ཡོངས་རྫོགས་ཚུད་དེ་ཡོད། དངུལ་སྤྲོད་འདི་ཐེམ་ཤོག་གསརཔ་ཅིག་ནང་ Paddle གིས་འབདཝ་ཨིན།','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'དྲ་རྒྱ་འདི་ནང་ག་ར་གི་དྲྭ་ས་ཁོངས་ཀྱིས་མཉམ་སྤྱོད་འབད་མི་ཡིག་སྒྱུར་ཡིག་ཆ་ཚུ་བསྒྱུར་བཅོས་འབདཝ་ལས་ དྲ་རྒྱའི་འགོ་འཛིན་པ་རྐྱངམ་ཅིག་གིས་འདི་འབད་ཚུགས།','Only plugins and themes can be packaged.'=>'ཁ་སྣོན་དང་ བཀོད་ཐབས་རྐྱངམ་ཅིག་ཐུམ་སྒྲིལ་འབད་ཚུགས།','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'WordPress.org ནང་མེད་པའི་པླགིན་ཡང་ན་ བརྡ་མཚོན་དཔེ་རྣམ་ (theme) ཅིག་གི་ཡར་སྤེལ་ཁྱེད་ཀྱིས་ངེས་གཏན་བཟོ་བའི་སྐབས་རྐྱངམ་ཅིག་ གསང་བའི་དངོས་པོ་དང་མཚུངས་པའི་ཡིག་སྣོད་ཚུ་བཏོན་ཚརཝ་ཅིག་གི་ཤུལ་ལས་ ཟིཔ་ཅིག་སྦེ་ཡར་སྤེལ་འབད་ཨིན། ཡིག་སྣོད་དེ་ཚུ་ཡང་ .php དང་ .js ཡིག་སྣོད་ཆ་མཉམ་ block.json ཡིག་སྣོད་ཆ་མཉམ་ དེ་ལས་ཆ་ཤས་དེའི་གཙོ་བོའི་ཡིག་སྣོད་ནང་གི་ readme.txt, readme.md, style.css དང་ theme.json ཚུ་ཨིན།','Open Babilim settings'=>'Babilim སྒྲིག་བཀོད་ཁ་ཕྱེ','Original language'=>'original སྐད་ཡིག','Original string'=>'ཡིག་ཕྲེང་ཐོག་མ།','Paid'=>'རིན་སྤྲོད་དགོཔ།','Partner'=>'མཉམ་རོགས','Please check that your site can be reached from the internet, then try again.'=>'ཁྱེད་ཀྱི་དྲྭ་ས་ཁོངས་ལུ་ ཡོངས་འབྲེལ་ལས་འཛུལ་ཚུགསཔ་ཨིན་མིན་ཞིབ་དཔྱད་འབད་ཞིན་ཏེ་ ལོག་ཚོད་ལྟ་འབད་གནང་།','Please choose a category for this report.'=>'སྙན་ཞུ་འདི་གི་དོན་ལུ་སྡེ་ཚན་ཅིག་འདེམས་གནང་།','Plugin'=>'པླག་ཨིན','Plugin · %s'=>'པ་ལུ་གིན · %s','Plugins'=>'པ་ལུ་གིན་ཚུ','Preview'=>'སྔོན་མཐོང་།','Purchase restored. This site is now licensed.'=>'ཉོ་སྒྲུབ་སླར་གསོ་འབད་ཡི། ཝེབ་སཱའིཊ་འདི་ད་ལྟོ་ཆོག་མཆན་ཐོབ་ཡོད།','Re-parsed entry count did not match the built index.'=>'ལོག་དབྱེ་ཞིབ་འབད་ཡོད་པའི་ཐོ་གྲངས་འདི་ བཟོ་ཡོད་པའི་ཐོ་ཡིག་དང་མཐུན་མ་སོང་།','Re-verify'=>'ར་སྤྲོད་ལོག་འབད','Rebuild index now'=>'ད་ལྟོ་ཟུར་ཐོ་བསྐྱར་བཟོ་འབད།','Refusing to write outside the Babilim language-file directory.'=>'Babilim གི་ སྐད་ཡིག་ཡིག་ཆ་སྣོད་ཐོ་ཕྱི་ལུ་ འབྲི་ནི་ ངོས་ལེན་མ་འབད།','Registration response was missing required fields.'=>'ཐོ་འགོད་ཀྱི་ལན་ནང་ དགོས་མཁོ་ཅན་གྱི་ས་སྒོ་ཚུ་བརླག་སྟེ་ཡོད།','Registration restarted.'=>'ཐོ་བཀོད་ལོག་འགོ་བཙུགས་ཅི།','Remove'=>'རྩ་བསྐྲད།','Remove everything Babilim installed'=>'Babilim གིས་གཞི་བཙུགས་འབད་མི་ག་ར་བཏོན་གཏང་','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim གིས་གཞི་བཙུགས་འབད་མི་ག་ར་བཏོན་གཏང་ནི་ཨིན་ན? འདི་གིས་དྲ་ཚིགས་འདི་ནང་གི་འཇུག་ཆས་དང་ དྲ་ཚིགས་བརྗོད་གཞི་ (theme) ག་ར་གི་དོན་ལུ་ Babilim གིས་གཞི་བཙུགས་འབད་མི་ སྐད་ཡིག་ཡིག་ཆ་ཆ་མཉམ་བཏོན་གཏང་འོང་།','Remove the %2$s translation of %1$s from this site?'=>'ས་ཁོངས་འདི་ལས་ %1$s གི་ %2$s ཡིག་སྒྱུར་བསུབ་ན?','Removed %d installed component.'=>'སྒྲིག་བཙུགས་འབད་ཡོད་པའི་ཆ་ཤས་ %d ཕྱིར་བཏོན་འབད་ཡོད།','Removed after a failed integrity check'=>'ཆ་ཚང་བའི་ཞིབ་དཔྱད་འཐུས་ཤོར་བྱུང་བའི་ཤུལ་ལས་རྩ་བསྐྲད་བཏང་ཡི།','Removed.'=>'བཏོན་ཅི།','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'དྲྭ་ས་ཁོངས་འདི་གི་ པླག་ཨིན་དང་ ཐིམ་ག་ར་གི་དོན་ལུ་ Babilim གིས་གཞི་བཙུགས་འབད་མི་ སྐད་ཡིག་ཡིག་ཆ་ག་ར་ རྩ་བསྐྲད་གཏང་།','Report a problem'=>'དཀའ་ངལ་ཅིག་སྙན་ཞུ་འབད།','Report translation'=>'ཁ་བསྒྱུར་སྙན་ཞུ་འབད།','Request newer translation'=>'ཡིག་སྒྱུར་གསར་པ་ཞུ','Request translation'=>'ཡིག་སྒྱུར་ཞུ','Requestable'=>'ཞུ་ཚུགསཔ','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Translation ཞུ་བའི་སྐབས་ plugin ཡང་ན་ theme འདི་ དྲ་ཚིགས་འདི་གི་རིན་མེད་ཞབས་ཏོག་འཆར་གཞིའི་སྒོ་སྒྲིག་གཅིག་གུ་བཞག་ཨིན། (ཚད་བཀག་འདི་ themes གི་ཆེད་དུ་ %1$d དང་ plugins གི་ཆེད་དུ་ %2$d ཨིན།) འདི་ལུ་སྒོ་སྒྲིག་གཅིག་ཧེ་མ་ལས་ཡོད་པ་ཅིན་ དེ་བཟུམ་མེན། སྒོ་སྒྲིག་དེ་ལག་ལེན་འཐབ་མི་སྦེ་ལུསཔ་ཨིནམ་དང་ འཐུས་ཤོར་བའི་ Translation གིས་དེ་མི་གློད།','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Translation ཞུ་བའི་སྐབས་ plugin ཡང་ན་ theme འདི་ དྲ་ཚིགས་འདི་གི་རིན་མེད་ཞབས་ཏོག་འཆར་གཞིའི་སྒོ་སྒྲིག་གཅིག་གུ་བཞག་ཨིན། འདི་ལུ་སྒོ་སྒྲིག་གཅིག་ཧེ་མ་ལས་ཡོད་པ་ཅིན་ དེ་བཟུམ་མེན། སྒོ་སྒྲིག་དེ་ལག་ལེན་འཐབ་མི་སྦེ་ལུསཔ་ཨིནམ་དང་ འཐུས་ཤོར་བའི་ Translation གིས་དེ་མི་གློད།','Requesting…'=>'ཞུ་དོ…','Restart registration'=>'ཐོ་བཀོད་ལོག་འགོ་བཙུགས','Restore code'=>'སླར་གསོ་ཀོཌ','Restore purchase'=>'ཚོང་འབྲེལ་སླར་གསོ','Retry request'=>'ཞུ་བ་ལོག་ཚོད་ལྟ་འབད','Roll back'=>'ཕྱིར་ལོག','Roll back and report'=>'ཕྱིར་ལོག་འབད་ཞིནམ་ལས་སྙན་ཞུ་འབད','Roll back and send report'=>'ཕྱིར་ལོག་འབད་ཞིནམ་ སྙན་ཞུ་གཏང་','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s གི་ %2$s ཡིག་སྒྱུར་འདི་ བཟོ་བསྐྲུན་ཧེ་མམ་ལུ་ ཕྱིར་ལོག་འབད་ནི་ཨིན་ན?','Rolled back and reported.'=>'ཕྱིར་སློག་འབད་ཚུགས་ཅི། སྙན་ཞུ་ཡང་འབད་ཅི།','Rolled back to the previous build.'=>'ཧེ་མམ་གྱི་བཟོ་བསྐྲུན་ལུ་ཕྱིར་སློག་འབད་ཚུགས་ཅི།','Rolled back, but the report could not be sent: %s'=>'ཕྱིར་སློག་འབད་ཚུགས་ཅི་ འདི་ཡང་ སྙན་ཞུ་གཏང་མ་ཚུགས: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'སླར་ལོག་འབད་བ་ཅིན་ \'%1$s\' (%2$s) ཐོག་ལུ་ བྲིས་འགྱོ་འོང་། འདི་ ད་ལྟོ་ གཞི་བཙུགས་འབད་ཡོད་པའི་ཆ་ཤས་གཞན་ཅིག་ (%3$s) གི་དོན་ལུ་ བཀྲམ་སྤེལ་འབད་དེ་ཡོདཔ་ལས་ ཅི་ཡང་མ་བསྒྱུར།','Rotate-token response was missing site_token.'=>'Rotate-token ལན་ནང་ site_token མེདཔ་ཐལ།','Save changes'=>'བསྒྱུར་བཅོས་ཚུ་ཉར་ཚགས་འབད','Scheduled, waiting to be processed'=>'དུས་བཀོད་འབད་ཡི། ལས་སྒྲུབ་ཚུགས་ནི་ལུ་ལྟ་སྡོད་ཡོད།','Search'=>'འཚོལ།','Search components'=>'ཆ་ཤས་ཚུ་འཚོལ།','Search the installed translations'=>'གཞི་བཙུགས་འབད་ཡོད་པའི་ཁ་བསྒྱུར་ཚུ་ འཚོལ།','Select all'=>'ཆ་མཉམ་སེལ་འཐུ་འབད','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'ཆ་ཤས་ཉུང་ཉུང་འདེམས་གནང་: གཡོག་བཀོལ་ཐེངས་རེ་ལུ་ བྱ་སྤྱོད་%1$d ལས་མ་ལྷག་པ་ (ཁྱེད་ཀྱིས་%2$d འདེམས་ཡི།)།','Send report'=>'སྙན་ཞུ་གཏང་','Service plan'=>'ཞབས་ཏོག་འཆར་གཞི','Settings'=>'སྒྲིག་བཀོད','Share error reports'=>'འཛོལ་བའི་སྙན་ཞུ་ བརྒྱུད་སྤྲོད་འབད།','Share this report'=>'སྙན་ཞུ་འདི་ བརྒྱུད་སྤྲོད་འབད།','Show a new restore code'=>'སླར་གསོ་ཀོཌ་གསརཔ་ཅིག་སྟོན','Show the "Report translation" entry in the admin toolbar'=>'འཛིན་སྐྱོང་ལག་ཆའི་ཚར་ཐིག་ནང་ "ཁ་བསྒྱུར་སྙན་ཞུ་འབད་ནི" ཐོ་བཀོད་སྟོན།','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'ཆ་ཤས་འདི་གི་ ཚིག་ཡིག་ལ་ལོ་ཅིག་ གསརཔ་བཟོ་མི་གིས་ ཐད་ཀར་བཀོད་ཡོདཔ་ལས་ སྐད་ཡིག་ཐུམ་སྒྲིལ་གྱིས་ སྒྱུར་མི་ཚུགས།','Status'=>'གནས་སྟངས','Status unknown'=>'གནས་སྟངས་མ་ཤེསཔ','String context'=>'ཡིག་ཕྲེང་གི་སྐབས་དོན','Suggested translation'=>'བསམ་འཆར་བཀོད་པའི་ཡིག་སྒྱུར','Supplementary translation index'=>'ཁ་སྐོང་གི་ཡིག་སྒྱུར་གྱི་སྟོན་གྲངས','Supplementary translation index rebuilt.'=>'ཁ་སྐོང་ཡིག་སྒྱུར་གྱི་སྟོན་གྲངས་ ལོག་བཟོ་ཅི།','Supplementary translation maintenance'=>'ཁ་སྐོང་ཡིག་སྒྱུར་གྱི་ཉམས་གསོ','Supplementary translations'=>'ཁ་སྐོང་གི་ཡིག་སྒྱུར་ཚུ','Sweep aborted without orphaning anything: %s.'=>'ཅི་ཡང་བདག་པོ་མེད་པ་མ་བཟོ་བར་ བསལ་གཏང་ནི་ བཀག་ཡོདཔ: %s།','Sweep complete: %d file deleted.'=>'བསལ་གཏང་ཚར་ཅི: ཡིག་སྣོད་ %d བསུབ་ཡོད།','Sweep now'=>'ད་ལྟ་བསལ་གཏང་','Sync complete.'=>'མཐུན་སྒྲིག་ཚར་ཅི།','Thank you. Your report was sent.'=>'ཐུགས་རྗེ་ཆེ། ཁྱེད་ཀྱི་སྙན་ཞུ་བཏང་ཡི།','That component is not installed on this site, so a translation cannot be requested for it.'=>'ཆ་ཤས་དེ་དྲྭ་ས་ཁོངས་འདི་ལུ་གཞི་བཙུགས་མ་འབད་བའི་ཁར་ དེ་གི་དོན་ལུ་ཡིག་སྒྱུར་ཞུ་མི་ཚུགས།','That does not look like a restore code.'=>'འདི་སླར་གསོ་ཀོཌ་ཅིག་བཟུམ་མིན་འདུག','That is not a valid WordPress locale code. Nothing was saved.'=>'དེ་ནི་ ནུས་ཅན་གྱི་ WordPress སྐད་ཡིག་ས་ཁོངས་ཨང་རྟགས་མེན། ཅི་ཡང་གསོག་འཇོག་མ་འབད།','That is not a valid build identifier.'=>'དེ་འདི་ ནུས་ཅན་གྱི་ བཟོ་བསྐྲུན་ངོས་འཛིན་ཅིག་མ་ཨིན།','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'སྐྱེལ་འཇུག་གི་བརྙན་ཁ་དེ་དུས་ཡུན་ལས་ཡོལ་ཞིནམ་ཨིན། དེའི་ཤུལ་ལས་སྐྱེལ་འཇུག་གཞན་ཅིག་གྲ་སྒྲིག་འབད་ཡོདཔ་ལས་ ཅི་ཡང་མ་བཏངཝ་ཨིན། Translations ཚོགས་ཐོ་ལས་ད་ལྟོའི་དེ་བསྐྱར་ཞིབ་འབད།','The change could not be recorded in the translation index; please try again.'=>'བསྒྱུར་བཅོས་འདི་ ཡིག་སྒྱུར་གྱི་སྟོན་གྲངས་ནང་ཐོ་བཀོད་འབད་མ་ཐུབ། ཁྱོད་ཀྱིས་ལོག་ཚོད་ལྟ་འབད།','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'གཙང་བཟོ་འདི་ གཡོག་བཀོལ་ཡི། འདི་འབདཝ་ད་ འགྱུར་བ་ལ་ལོ་ཅིག་ ཡིག་སྒྱུར་གྱི་སྟོན་གྲངས་ནང་ ཐོ་བཀོད་འབད་མ་ཚུགས། ཤུལ་མམ་གཙང་བཟོ་གིས་ ལོག་ཚོད་ལྟ་འབདཝ་ཨིན།','The component has no files that can be uploaded.'=>'ཆ་ཤས་འདི་ལུ་ཡར་སྤེལ་འབད་ཚུགས་པའི་ཡིག་སྣོད་མིན་འདུག','The component is not inside the plugins or themes directory.'=>'ཆ་ཤས་འདི་ ཁ་སྣོན་ཡང་ན་ བཀོད་ཐབས་ཀྱི་སྣོད་ཐོའི་ནང་མེན།','The component\'s main file was not found.'=>'ཆ་ཤས་ཀྱི་ཡིག་ཆ་གཙོ་བོ་ མ་ཐོབ།','The download response was missing a usable location.'=>'ཕབ་ལེན་གྱི་ལན་ནང་ ལག་ལེན་འཐབ་ཚུགས་པའི་ས་གནས་མ་འདུག','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'ཐོ་བཀོད་འདི་གིས་ Babilim གིས་ཝེབ་ས་ཁོངས་འདི་ལུ་གཞི་བཙུགས་འབད་ཡོད་པའི་ཁ་བསྒྱུར་ཚུ་འཚོལ་ནི་དང་ དེ་ཚུ་ལས་གཅིག་སྙན་ཞུ་འབད་ནིའི་དོན་ལུ་ པེ་ནཱལ་ཅིག་ཁ་ཕྱེཝ་ཨིན།','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'ཡིག་ཆ་བཀོད་ས་ "%1$s" རིངམ་དྲག་སོང་: ཡིག་འབྲུ་%2$d ཡོད་པའི་ཁར་ ཚད་བཀག་འདི་%3$d ཨིན། ཅི་ཡང་མ་བཏང་; ཐུང་ཀུ་བཟོ་ཞིན་ཏེ་ ལོག་ཚོད་ལྟ་འབད་གནང་།','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'རིན་མེད་ཞབས་ཏོག་འཆར་གཞིའི་ཐོག་ལས་ དྲ་ཚིགས་རེ་རེ་ལུ་ plugins དང་ themes ཚུ་གི་ཆེད་དུ་ སྒོ་སྒྲིག་ཚུ་གྲངས་ཚད་ཅན་ཅིག་སྤྲོདཔ་ཨིན། Babilim ལྕོགས་ཅན་བཟོ་ཚརཝ་ད་ ལག་ལེན་འཐབ་ཡོད་པའི་སྒོ་སྒྲིག་ཚུ་ Settings ནང་སྟོནམ་ཨིན།','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'བྱིན་པའི་ཁྱབ་ཁོངས་ \'%1$s\' འདི་ ཐུམ་སྒྲིལ་མེནི་ཕེསཊ་གི་ slug \'%2$s\' དང་ text_domain \'%3$s\' གཉིས་ཆ་ར་དང་མི་མཐུན་པས།','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' གི་མཉམ་སྡེབ་སྟོན་གྲངས་ སླར་བཟོ་ཚར་ཡི། འོན་ཀྱང་ ཡིག་སྒྱུར་གྱི་སྟོན་གྲངས་ཀྱིས་ཐོ་བཀོད་འབད་མ་ཐུབ། ཤུལ་མམ་གྱི་སླར་བཟོ་འབད་བའི་སྐབས་ ལོག་ཚོད་ལྟ་འབད་འོང་།','The original text and the translations made from it will be provided to other sites that install the same version.'=>'ཡིག་ཆ་གདོད་མ་དང་ དེ་ལས་བཟོ་མི་ཡིག་སྒྱུར་ཚུ་ ཐོན་རིམ་གཅིག་པ་གཞི་བཙུགས་འབད་མི་ ཝེབ་ས་ཁོངས་གཞན་ཚུ་ལུ་བྱིན་འོང་།','The package declares no main translation file.'=>'ཐུམ་སྒྲིལ་འདི་ནང་ ཚིག་སྒྱུར་གྱི་ཡིག་ཆ་གཙོ་བོ་ གསལ་བསྒྲགས་མ་འབད་བས།','The package has no %s for its own text domain.'=>'ཐུམ་སྒྲིལ་ལུ་ རང་གི་ཚིག་ཡིག་ཁྱབ་ཁོངས་ཀྱི་དོན་ལུ་ %s མེད།','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'ཐུམ་སྒྲིལ་མེནི་ཕེསཊ་གི་དབྱེ་བ་ \'%1$s\' འདི་ ཞུ་བ་འབད་ཡོད་པའི་དབྱེ་བ་ \'%2$s\' དང་མི་མཐུན་པས།','The package produced no servable main translation file.'=>'ཐུམ་སྒྲིལ་འདི་གིས་ ལག་ལེན་འཐབ་ཚུགསཔ་གི་ ཡིག་སྒྱུར་ཡིག་ཆ་གཙོ་བོ་ མ་བཟོ་བས།','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'ཐུམ་སྒྲིལ་གྱི་ཚིག་ཡིག་ཁྱབ་ཁོངས་ \'%1$s\' འདི་ ཝེབ་ས་ཁ་འདི་གི་ཆ་ཤས་ཀྱི་འདྲ་བཤུས་ (\'%2$s\') དང་མི་མཐུན་པའི་ཁར་ གཞི་བཙུགས་མ་འབད།','The packaged component could not be read.'=>'ཐུམ་སྒྲིལ་འབད་ཡོད་པའི་ཆ་ཤས་ལྷག་མ་ཚུགས།','The registration challenge is not in the expected form.'=>'ཐོ་བཀོད་ཀྱི་བརྟག་དཔྱད་(challenge) འདི་ རེ་བ་བསྐྱེད་པའི་རྣམ་པ་ནང་མེདཔ་ཨིན།','The report could not be sent.'=>'སྙན་ཞུ་འདི་ བསྐུར་མ་ཚུགས།','The search could not be completed.'=>'འཚོལ་ཞིབ་འདི་ མཇུག་མ་བསྡུ་ཚུགས།','The service asked this site to wait before syncing again.'=>'ཞབས་ཏོག་གིས་ས་ཁོངས་འདི་ལུ་ ལོག་མཉམ་འབྱུང་མ་འབད་བའི་ཧེ་མ་ བསྒུག་དགོ་ཟེར་ཞུ་ཡི།','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'ཞབས་ཏོག་གིས་ཁྱེད་རའི་དྲ་ཚིགས་ལུ་ལྷོད་མ་ཚུགས། མེ་རྒྱ་ ཉེན་སྲུང་འཇུག་ཆས་ ཡང་ན་ཧོསཊི་གི་སྒྲིག་ལམ་གྱིས་ཞུ་བ་འདི་བཀག་ཅི་འོང་ས་ཡོད། /wp-json/babilim/v1/challenge ལུ་ཞུ་བ་འབད་ནིའི་ཆོག་ཐམ་སྤྲོད་གནང་།','The service\'s upload offer was incomplete.'=>'ཞབས་ཏོག་གིས་བྱིན་མི་ཡར་སྐྱེལ་གྱི་ལམ་སྟོན་འདི་ཆ་མ་ཚང་པས།','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'ཚིག་ཡིག་ཁྱབ་ཁོངས་ \'%1$s\' (%2$s) འདི་ གཞི་བཙུགས་འབད་ཡོད་པའི་ཆ་ཤས་གཞན་ཅིག་ (%3$s) གི་དོན་ལུ་ ཧེ་མ་ལས་རང་ བཀྲམ་སྤེལ་འབད་དེ་ཡོད། ཅི་ཡང་གཞི་བཙུགས་མ་འབད།','The upload is kept until you ask Babilim to delete it.'=>'ཁྱོད་ཀྱིས་ Babilim ལུ་བཏོན་གཏང་ནིའི་ཞུ་བ་མ་བཀོད་ཚུན་ ཡར་སྐྱེལ་འདི་ཉར་ཚགས་འབད་ཡོད།','Theme'=>'དྲ་ཚིགས་བརྗོད་གཞི་ (Theme)','Theme · %s'=>'ཐིམ · %s','Themes'=>'ཐིམ་ཚུ','There is no upload in progress.'=>'ཡར་བསྐྱལ་འབད་དེ་ཡོད་མི་ཅིག་ཡང་མིན་འདུག','There is no upload waiting for confirmation.'=>'ངེས་འཛིན་ལུ་སྒུག་སྟེ་ཡོད་པའི་ཡར་སྐྱེལ་ཅིག་ཡང་མིན་འདུག','These are the languages this site uses. You can change them in %s.'=>'འདི་ཚུ་ ཝེབ་ས་ཁོངས་འདི་གིས་ལག་ལེན་འཐབ་མི་ སྐད་ཡིག་ཚུ་ཨིན། ཁྱོད་ཀྱིས་ %s ནང་ལས་བསྒྱུར་ཚུགས།','These fields will be sent:'=>'ས་སྒོ་འདི་ཚུ་ བསྐུར་འོང་།','This build is not one this site currently knows about for this component/locale.'=>'བཟོ་བསྐྲུན་འདི་ ཆ་ཤས་/སྐད་ཡིག་ས་ཁོངས་འདི་གི་དོན་ལུ་ ཝེབ་ས་ཁ་འདིས་ད་ལྟོ་ཤེས་མི་ཅིག་མེན།','This component does not declare a version number, so a translation cannot be requested for it.'=>'ཆ་ཤས་འདི་གིས་ཐོན་རིམ་ཨང་གྲངས་མ་བསྒྲགས་པའི་ཁར་ དེ་གི་དོན་ལུ་ཡིག་སྒྱུར་ཞུ་མི་ཚུགས།','This component is larger than the service accepts, so it cannot be uploaded.'=>'ཆ་ཤས་འདི་ ཞབས་ཏོག་གིས་ངོས་ལེན་འབད་མི་ལས་ཆེ་བས་ སྤྲོད་འབུལ་འབད་མི་ཚུགས།','This component was already uploaded. Babilim is checking it now.'=>'ཆ་ཤས་འདི་ཧེ་མ་ལས་ཡར་བཙུགས་འབད་ཡོད། Babilim གྱིས་ད་ལྟོ་ཞིབ་དཔྱད་འབད་དོ་ཡོད།','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'ཆ་ཤས་འདི་གི་ཐོན་རིམ་ཨང་གྲངས་འདི་ཡིག་འབྲུ་%d ལས་རིངམ་ཡོདཔ་ལས་ Babilim གིས་ལག་ལེན་འཐབ་མི་ཚུགས། དེ་འབདཝ་ལས་ དེ་གི་དོན་ལུ་ཡིག་སྒྱུར་ཞུ་མི་ཚུགས།','This issues a new restore code and the previous one stops working. Continue?'=>'འདི་གིས་ སླར་གསོ་ཀོཌ་གསརཔ་ཅིག་སྤྲོདཔ་ཨིནམ་ལས་ ཧེ་མམ་གྱི་དེ་ལཱ་མ་འབད་ཚུགས། འཕྲོ་མཐུད་ནི་ཨིན་ན?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'དྲ་བསྒྲིགས་འདི་ལུ་ ཝེབ་ས་ཁ་མང་དྲགས་ཏེ་རེ་རེ་བཞིན་ཞིབ་དཔྱད་འབད་མི་ཚུགས། ཁོང་ཚུ་གི་ནང་ལས་ལ་ལོ་ཅིག་གིས་ པླག་ཨིན་བསུབ་པའི་སྐབས་ Babilim ངོ་རྟགས་བསུབ་གཏང་ནིའི་ གཞི་སྒྲིག་འབད་ཡོདཔ་འོང་ནི་ཨིན། དེ་བཟུམ་མའི་ཝེབ་ས་ཁ་ལུ་མཚམས་སྦྱར་ཡོད་པའི་འཐུས་ཀྱི་ཆོག་ཐམ་འདི་ རང་བཞིན་གྱིས་སླར་གསོ་འབད་མི་ཚུགས། %s ལུ་ Babilim རྒྱབ་སྐྱོར་ལུ་འབྲེལ་བ་འཐབ་དགོ། ངོ་རྟགས་སྲུང་ནིའི་དོན་ལུ་ "ཆ་མེད་" ལུ་ཨེབ་ཞིནམ་ལས་ ཝེབ་ས་ཁ་རེ་རེའི་ Babilim སྒྲིག་བཀོད་ནང་ "སྒྲིག་འཇུག་མེདཔ་བཟོཝ་འི་སྐབས་ Babilim གྱི་གནས་སྡུད་ཆ་མཉམ་ བསུབ་གཏང་" གི་རྟགས་བསུབ་སྟེ་ པླག་ཨིན་འདི་ ལོག་ལག་ལེན་མེད་བཟོ། དེ་ལས་ཀྱང་ ལག་ལེན་མེད་བཟོ་ནི་ཨིན་ན?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'ལག་ཆས་འདི་གི་རང་ཉིད་ཀྱི་ཐོན་རིམ། དེ་གིས་ཐོན་རིམ་རྙིང་དྲགས་སྦེ་ཞབས་ཏོག་དང་འབྲེལ་བ་འཐབ་མ་ཚུགསཔ་ད་ ཞབས་ཏོག་གིས་ཁྱེད་ལུ་ཐོན་རིམ་གསར་བསྒྱུར་འབད་ནིའི་བརྡ་བསྐུལ་འབད་ཚུགས།','This report does not name a valid plugin or theme and locale.'=>'སྙན་ཞུ་འདི་ཡིས་ ནུས་ཅན་གྱི་པླག་ཨིན་ ཡང་ན་ ཐིམ་དང་ སྐད་ཡིག་ས་ཁོངས་ མིང་བཀོད་མི་འདུག','This report does not name an installed string.'=>'སྙན་ཞུ་འདི་གིས་ སྒྲིག་འཇུག་འབད་ཡོད་པའི་ཚིག་ཕྲེང་ཅིག་གི་མིང་མི་བརྗོདཔ་ཨིན།','This report is missing a valid build to report against.'=>'སྙན་ཞུ་འདི་ལུ་ སྙན་ཞུ་འབད་ནིའི་ནུས་ཅན་གྱི་བཟོ་བསྐྲུན་ཅིག་མིན་འདུག','This report will be posted publicly on GitHub and may be kept by third parties.'=>'སྙན་ཞུ་འདི་ GitHub གུ་ མི་མང་ལུ་ སྤེལ་འོང་ཞིནམ་ལས་ ཕྱོགས་གསུམ་པ་ཚུ་གིས་ ཉར་ཚགས་འབད་ནི་འོང་།','This restore code was not recognised for this site.'=>'སླར་གསོ་ཀོཌ་འདི་ ས་ཁོངས་འདི་གི་དོན་ལུ་ངོས་མ་ཟིན།','This site already has an active registration that can no longer be recovered automatically.'=>'དྲྭ་ས་ཁོངས་འདི་ལུ་ད་ལྟོ་ལག་ལེན་འཐབ་བཞིན་པའི་ཐོ་བཀོད་ཅིག་ཡོདཔ་ད་ འདི་རང་འགུལ་གྱིས་སླར་རྙེད་མི་ཚུགས།','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'ཝེབ་ས་ཁ་འདི་ལུ་ སྐད་ཡིག་%2$d གི་ཆ་ཤས་%1$d ཡོད་ནི་དང་ དེ་གི་དོན་ལུ་ ཞིབ་དཔྱད་ཀྱི་ཚན་པ་%3$d དགོཔ་ཨིན། Babilim གིས་ གཡོག་བཀོལ་རེ་ལུ་ མང་ཤོས་ཀྱི་ཚད་%4$d རྐྱངམ་ཅིག་ལག་ལེན་འཐབ་ཚུགས། སྒྲིག་བཀོད་ནང་ལས་ འཛིན་སྐྱོང་འབད་མི་སྐད་ཡིག་ཚུ་ཉུང་དུ་གཏང་ ཡང་ན་ ལག་ལེན་མེད་པའི་པླག་ཨིན་དང་ཐིམ་ཚུ་ ལག་ལེན་མེད་བཟོ་ཞིནམ་ལས་ ད་ལྟ་ལོག་ཞིབ་དཔྱད་འབད་ལུ་ཨེབ།','This site has no purchase to show a code for.'=>'ཝེབ་སཱའིཊ་འདི་ལུ་ཨང་རྟགས་སྟོན་ནིའི་ཉོ་སྒྲུབ་མིན་འདུག','This site is already licensed. Reload the page.'=>'དྲྭ་ས་ཁོངས་འདི་ལུ་ཧེ་མ་ལས་ཆོག་ཐམ་ཡོད། ཤོག་ལེབ་ལོག་མངོན།','This site is not registered with Babilim yet.'=>'དྲྭ་ས་ཁོངས་འདི་ Babilim ལུ་ད་ལྟོ་ཚུན་ཐོ་བཀོད་མ་འབད་ཡི།','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'ཝེབ་ས་ཁ་འདི་ ཞབས་ཏོག་གིས་མཉམ་འགྲིག་ཚར་གཅིག་ནང་ངོས་ལེན་འབད་པའི་ཚད་ལས་ལྷག་སྟེ་ཡོད་ནི་ལས་ རྣམ་གྲངས་ལ་ལུ་བཏོན་བཞག་ཡོད། ཆ་ཤས་ %1$d དང་ སྐད་ཡིག་ས་ཁོངས་ %2$d ཨིན།','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'དྲྭ་ས་ཁོངས་འདི་དྲྭ་ས་ཁོངས་མང་པོའི་དྲ་རྒྱའི་ཆ་ཤས་ཅིག་ཨིནམ་ལས་ ཡིག་སྒྱུར་གསརཔ་ཚུ་རང་འགུལ་གྱིས་སྒྲིག་བཙུགས་མི་འབད། ཡིག་སྒྱུར་སྒྲིག་བཙུགས་འབད་ཏེ་ཡོད་མི་ཚུ་ཡང་ད་ལྟོ་ཡང་དུས་མཐུན་བཟོཝ་ཨིན།','This site is verified.'=>'ཝེབ་ས་ཁ་འདི་ ངེས་དཔྱད་འབད་ཡོད།','This site must be verified first.'=>'ས་ཁོངས་འདི་ དང་པོ་ངེས་དཔྱད་འབད་དགོ།','This site\'s URL, so the service can verify you own it.'=>'དྲ་ཚིགས་འདིའི་ URL, དེ་གིས་ཞབས་ཏོག་གིས་ཁྱོད་དེའི་བདག་པོ་ཨིན་པ་ངེས་དཔྱད་འབད་ཚུགས་ནིའི་དོན་ལུ།','This site\'s address is too long for Babilim to register.'=>'ཝེབ་ས་ཚིགས་འདི་གི་ཁ་བྱང་ ཧ་ཅང་རིང་པས་ Babilim གིས་ཐོ་འགོད་འབད་མི་ཚུགས།','This site\'s configured locale.'=>'དྲ་སྟོན་འདི་གི་ སྒྲིག་བཀོད་འབད་ཡོད་པའི་ས་ཁོངས་སྐད་ཡིག','This site\'s locale code is not one Babilim can register.'=>'ས་ཁོངས་འདི་གི་སྐད་ཡིག་ཀོཌ་འདི་ Babilim གིས་ཐོ་བཀོད་འབད་མི་ཚུགས་པའི་ཀོཌ་ཅིག་ཨིན།','This string can\'t be reported from this site.'=>'ཡིག་ཕྲེང་འདི་ ས་ཁོངས་འདི་ལས་ སྙན་ཞུ་འབད་མི་ཚུགས།','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'ཚིག་ཕྲེང་འདི་ ས་ཁོངས་འདི་ནང་སྒྲིག་འཇུག་འབད་ཡོད་པའི་ཡིག་སྒྱུར་ཚུ་ནང་མིན་འདུག །ལོག་འཚོལ། ཞིནམ་ལས་ཐོ་ཡིག་ནང་ལས་སེལ་འཐུ་འབད།','This translation was updated since you searched. Search again and pick the string from the new list.'=>'ཁྱེད་ཀྱིས་འཚོལ་བའི་ཤུལ་ལས་ ཡིག་སྒྱུར་འདི་དུས་མཐུན་བཟོ་ཡོད། ལོག་འཚོལ། ཞིནམ་ལས་ཐོ་ཡིག་གསརཔ་ནང་ལས་ ཚིག་ཕྲེང་འདི་སེལ་འཐུ་འབད།','To translate this component, Babilim needs its source.'=>'ཆ་ཤས་འདི་ཡིག་སྒྱུར་འབད་ནི་ལུ་ Babilim གིས་ འབྱུང་ཁུངས་དགོཔ་ཨིན།','Too many attempts. Try again tomorrow.'=>'ཚོད་ལྟ་མང་དྲགས་འབད་ནུག ནངས་པ་ལོག་ཚོད་ལྟ་འབད།','Too many reports today. Try again tomorrow.'=>'དེ་རིང་ སྙན་ཞུ་མང་དྲག་སོང་། སང་ཉིན་ལོག་ཚོད་ལྟ་འབད།','Too many requests.'=>'ཞུ་བ་ཧ་ཅང་མང་དྲག།','Toolbar'=>'ལག་ཆའི་ཚར་ཐིག','Translating…'=>'ཡིག་སྒྱུར་འབད་བའི་སྒང་ཡོད…','Translation does not load'=>'ཡིག་སྒྱུར་འདི་མ་མངོན་པས།','Translation failed'=>'ཡིག་སྒྱུར་འཐུས་ཤོར་འབྱུང་ཡི།','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'ཁྱོད་ཀྱིས་ %s ནང་བཙུགས་མི་ཡིག་སྒྱུར་ཡིག་ཆ་ཚུ་ ག་དུས་ཡང་ Babilim གི་ཡིག་ཆ་ལས་གཙོ་རིམ་མཐོ་བ་ཨིན། ཁྱོད་ཀྱིས་འདི་ལས་རྟགས་མ་བཏོན་ཚུན་ཚོད་ བསྐྱངས་ཡོད།','Translation requested.'=>'ཡིག་སྒྱུར་ཞུ་ཡི།','Translations'=>'ཡིག་སྒྱུར','Type'=>'དབྱེ་བ།','Type at least 2 characters to search.'=>'འཚོལ་ནིའི་དོན་ལུ་ ཡིག་འབྲུ་ཉུང་ཤོས་༢ བཙུགས།','Unexpected HTTP %d response.'=>'རེ་བ་མེད་པའི་ HTTP %d ལན།','Uninstall'=>'བསུབ་','Unknown kind: %s'=>'ངོས་འཛིན་མ་འབད་བའི་དབྱེ་བ། %s','Unsafe domain: %s'=>'ཉེན་ཆ་ཅན་གྱི་ཁྱབ་ཁོངས། %s','Unsafe locale: %s'=>'ཉེན་སྲུང་མེད་པའི་ ས་ཁོངས་སྐད་ཡིག: %s','Unsafe slug: %s'=>'ཉེན་ཅན་གྱི་ slug: %s','Unsafe text_domain: %s'=>'བདེ་འཇགས་མེད་པའི་ text_domain: %s','Update'=>'དུས་མཐུན་བཟོ','Update available'=>'དུས་མཐུན་འབད་ཚུགས།','Updates'=>'དུས་མཐུན་ཚུ','Updating…'=>'དུས་མཐུན་བཟོ་དོ…','Upgrade this site'=>'ས་ཁོངས་འདི་ཡར་རྒྱས་གཏང་','Upload and request'=>'ཡར་སྐྱེལ་འབད་ཞིནམ་ལས་ཞུ།','Upload cancelled.'=>'ཡར་བཙུགས་འབད་ནི་ཆ་མེད་བཏང་ཡི།','Upload complete — translation requested.'=>'ཡར་བཙུགས་འབད་ཚར་ཡི། — ཡིག་སྒྱུར་ཞུ་ཡི།','Upload expired before it finished'=>'ཡར་བཙུགས་མཇུག་མ་བསྡུ་བའི་ཧེ་མ་ དུས་ཡུན་རྫོགས་སོང་།','Upload in progress — continue or cancel'=>'ཡར་བཙུགས་འབད་བའི་སྒང་ཡོད་ — འཕྲོ་མཐུད་ཡང་ན་ཆ་མེད་གཏང་།','Upload this component?'=>'ཆ་ཤས་འདི་ སྤར་ནི་ཨིན་ན?','Upload was not accepted'=>'ཡར་བཙུགས་ངོས་ལེན་མ་འབད་བས།','Uploading'=>'ཡར་སྐྱེལ་འབད་དེ་ཡོད','Uploading part %1$d of %2$d…'=>'ཆ་ཕྲན་ %2$d ཀྱི་ %1$d ཡར་སྐྱེལ་འབད་དེ་ཡོད…','Uploading…'=>'ཡར་སྐྱེལ་འབད་དེ་ཡོད…','Verified'=>'ངེས་དཔྱད་འབད་ཡོད','Verify response was missing site_token.'=>'བདེན་དཔྱད་ལན་ནང་ site_token མེདཔ་ཐལ།','Version %s'=>'ཐོན་རིམ་ %s','What is sent when you enable Babilim'=>'Babilim ལག་ལེན་འཐབ་ཚུགསཔ་བཟོཝ་ད་ གཏོང་མི་ཚུ།','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Babilim ནང་ག་ཅི་རུང་ ཕམ་པའི་སྐབས་ འཛོལ་བའི་སྙན་ཞུ་ཅིག་ Babilim ཞབས་ཏོག་ལུ་ བསྐུརཝ་ཨིན། དེ་ལས་ GitHub གུ་ མི་མང་གི་གནད་དོན་ཅིག་སྦེ་ སྤེལ་ཚུགས། སྙན་ཞུ་འདི་ ས་ཁོངས་འདི་ལས་ བྱུང་བའི་ཚུལ་གྱིས་ བསྐུརཝ་ཨིན་ལ་ Babilim ཞབས་ཏོག་ལུ་ བསྐུརཝ་ཡོད་པའི་ ཞུ་བ་གཞན་ཆ་མཉམ་དང་ འདྲ་བའི་ བདེན་བཤད་ (authentication) དང་ཅིག་ཁར་ བསྐུརཝ་ཨིན། ཞབས་ཏོག་གིས་ འཛོལ་བའི་ཨང་རྟགས་དང་ ཐོན་རིམ་ཚུ་རྐྱངམ་ཅིག་ GitHub གུ་ མི་མང་གི་གནད་དོན་སྦེ་ སྤེལཝ་ཨིན། མི་མང་གི་གནད་དོན་འདི་ནང་ ས་ཁོངས་ཀྱི་ཁ་བྱང་ ནང་དོན་ ཡང་ན་ ཡིག་ཆའི་ལམ་ཚུ་ གང་ཡང་མི་འདུག སྔོན་སྒྲིག་ལུ་ ཁ་བསྡམས་ཏེ་ཡོདཔ།','Where you saw this (optional)'=>'ཁྱེད་ཀྱིས་འདི་གང་ལུ་མཐོང་ཡི་ (འདོད་ན།)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'འདི་ཁ་ཕྱེ་ཡོད་པའི་སྐབས་ ཁྱོད་ཀྱིས་འཛིན་སྐྱོང་འབད་མི་སྐད་ཡིག་ཚུ་གི་དོན་ལུ་ ཞབས་ཏོག་གིས་ཐོབ་ཚུགསཔ་སྦེ་ཐོ་བཀོད་འབད་མི་ཡིག་སྒྱུར་ཚུ་ ཉིནམ་གཅིག་ལུ་ཕྱོགས་མཐུན་ལན་གཉིས་ཀྱི་སྐབས་ལུ་གཞི་བཙུགས་འབད་ཐོན་འོང་།','WordPress.org'=>'WordPress.org','Wrong for this context'=>'སྐབས་དོན་འདི་ལུ་ ཕྱིན་ཅི་ལོག','Wrong meaning'=>'དོན་ཚིག་ཕྱིན་ཅི་ལོག','Wrong plural form'=>'མང་ཚིག་གི་རྣམ་པ་ཕྱིན་ཅི་ལོག','Wrong term'=>'ཚིག་ཕྱིན་ཅི་ལོག','Yes'=>'ཨིན','You are not allowed to do this.'=>'ཁྱེད་ལུ་འདི་འབད་ནི་ལུ་ཆོག་མ་ཐོབ།','Your PHP version, for compatibility.'=>'ཁྱོད་ཀྱི་ PHP ཐོན་རིམ་, མཐུན་འཚམས་ཀྱི་དོན་ལུ།','Your WordPress version, to serve compatible translation files.'=>'ཁྱོད་ཀྱི་ WordPress ཐོན་རིམ། འཐུན་འཚམས་ཀྱི་ཡིག་སྒྱུར་ཡིག་སྣོད་ཚུ་བཀྲམ་སྤེལ་འབད་ནིའི་དོན་ལུ།','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'ཁྱོད་ཀྱི་སླར་གསོ་ཀོཌ་གསརཔ་: %s། ཉེན་སྲུང་ཅན་གྱི་ས་ཅིག་ལུ་བསྐྱངས། ཧེ་མམ་གྱི་ཀོཌ་འདི་ལཱ་མི་འབད།','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'ཁྱོད་ཀྱི་སྙན་ཞུ་འདི་ AI མོ་ཌལ་ཚུ་གིས་ རང་བཞིན་གྱིས་ ལས་སྦྱོར་འབདཝ་ཨིནམ་ལས་ ས་ཁོངས་གཞན་ཚུ་གི་དོན་ལུ་ ཁ་བསྒྱུར་འདི་ ལེགས་བཅོས་འབད་ཚུགས།','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'ཁྱེད་ཀྱི་ཝེབ་ས་ཁ་གིས་ ལན་བཏབ་ཅི་འདུག ཨིན་རུང་ རེ་བ་བསྐྱེད་མི་དང་མི་མཐུན། REST API འདི་ པླག་ཨིན་གཞན་ཅིག་གིས་ བསྐྱར་བྲིས་འབད་དེ་ཡོད་ཚུགས། ཡང་ན་ endpoint དེ་ cache འབད་དེ་ཡོད་ཚུགས། /wp-json/babilim/v1/challenge འདི་ cache དང་ བསྐྱར་བྲིས་ལས་ཕྱིར་འཐོན་འབད་གནང་།','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'ཁྱེད་རའི་ཝེབ་ས་ཁ་གིས་ལན་འདེབས་ནི་ལུ་དུས་ཚོད་རིང་དྲགས་སོ། ཤུལ་ལས་ཚར་གཅིག་ལོག་རྩོལ་གནང་། དེ་ལས་ཧོསཊ་འདི་ དལ་དྲགས་ ཡང་ན་ ཁུར་ཚད་ཆེ་དྲགས་མེད་པའི་ཞིབ་དཔྱད་འབད་གནང་།','Zip has no manifest.json.'=>'Zip ནང་ manifest.json མེད།','Zip is missing expected default file: %s'=>'Zip ནང་ རེ་བ་བསྐྱེད་མི་སྔོན་སྒྲིག་ཡིག་ཆ་ མེདཔ་འདུག %s','Zip is missing expected file: %s'=>'Zip ནང་ རེ་བ་བསྐྱེད་མི་ཡིག་ཆ་ མེདཔ་འདུག %s','_manifest.json has an unexpected structure'=>'_manifest.json ནང་ རེ་བ་མེད་པའི་གཞི་བཀོད་ཅིག་ཡོད།','could not read _manifest.json: %s'=>'_manifest.json ལྷག་མ་ཚུགས། %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest ནང་ \'%s\' མེདཔ་ཡང་ན་ ནུས་མེད་ཨིན།','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest གི་ \'server_build_id\' འདི་ བཟོ་བསྐྲུན་ ID ནུས་ཅན་མེན།','failed to parse _manifest.json: %s'=>'_manifest.json ཚིག་དཔྱད་འབད་མ་ཚུགས། %s','it would orphan %1$d of %2$d managed components (more than half)'=>'འདི་གིས་འཛིན་སྐྱོང་འབད་མི་ཆ་ཤས་ཚུ་ %2$d ནང་ལས་ %1$d བདག་པོ་མེད་པ་བཟོ་འོང་ (ཕྱེད་ལས་ལྷག་པ)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'འདི་གིས་འཛིན་སྐྱོང་འབད་མི་ %1$s ཆ་ཤས་ཆ་མཉམ་བདག་པོ་མེད་པ་བཟོ་འོང་ (%2$d ནང་ལས་ %2$d)','l10n.php entry count mismatch for %s'=>'%s གི་དོན་ལུ་ l10n.php ཐོ་བཀོད་ཀྱི་གྲངས་ཀ་མི་མཐུན་པས།','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ནང་ \'default_domain_entries\' ནུས་མེད་ཨིན།','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ནང་ \'default_domain_files\' ནུས་མེད་ཨིན།','manifest.json in the zip is not valid JSON.'=>'zip ནང་གི་ manifest.json འདི་ JSON ནུས་ཅན་མེན།','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json ནང་ \'%s\' མེདཔ་ཡང་ན་ ནུས་མེད་ཨིན།','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json ནང་ \'build_no\' མེདཔ་ཡང་ན་ ནུས་མེད་ཨིན།','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json ནང་ \'entries\' མེདཔ་ཡང་ན་ ནུས་མེད་ཨིན།','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json ནང་ \'extra_domains\' མེདཔ་ཡང་ན་ ནུས་མེད་ཨིན།','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json ནང་ \'files\' མེདཔ་ཡང་ན་ ནུས་མེད་ཨིན།','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json གི་ \'%s\' འདི་ རེ་བ་བསྐྱེད་པའི་གནས་གྲངས་དང་མི་མཐུན་པས།','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json གི་ \'contract\' འདི་ ཐོན་རིམ་ཡིག་རྐྱང་ནུས་ཅན་མེན།','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json གི་ \'kind\' འདི་ \'plugin\' ཡང་ན་ \'theme\' ཨིནམ་འོང་དགོ།','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json གི་ \'server_build_id\' འདི་ བཟོ་བསྐྲུན་ ID ནུས་ཅན་མེན།','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json གི་ \'status\' འདི་ \'published\' ཨིནམ་འོང་དགོ།','nonce must be a hexadecimal string.'=>'nonce འདི་ བཅུ་དྲུག་གྲངས་ཀྱི་ཡིག་རྐྱང་ཅིག་ཨིནམ་འོང་དགོ།','per day'=>'ཉིནམ་རེ་བཞིན།','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s གི་དོན་ལུ་ sha256 མི་མཐུན་པས།','sha256 mismatch for default/%s'=>'default/%s གི་དོན་ལུ་ sha256 མི་མཐུན་པས།','component kind in the sweep brake messageplugin'=>'ཁ་སྐོང་','component kind in the sweep brake messagetheme'=>'ཐིམ་','problem report categoryOther'=>'གཞན།','translation statusAvailable'=>'ཐོབ་ཚུགས་པ','translation statusInstalled'=>'གཞི་བཙུགས་འབད་ཡི།','Babilim translation turned off.'=>'Babilim ཡིག་སྒྱུར་བཀག་བཞག་ཡོད།','Stop using Babilim translation'=>'Babilim ཡིག་སྒྱུར་ལག་ལེན་འཐབ་མ་དགོ།','Use Babilim translation'=>'Babilim ཡིག་སྒྱུར་ལག་ལེན་འཐབ།','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) གི་ Babilim ཡིག་སྒྱུར་ལག་ལེན་འཐབ་མ་དགོ་ནི་ཨིན་ན། WordPress གིས་ དེ་གི་ཚབ་ཏུ་ ཐིམ་(theme)་དེ་རང་གི་ ཡང་ན་ WordPress.org ཡིག་སྒྱུར་ལག་ལེན་འཐབ་འོང་། ཁྱོད་ཀྱིས་ དུས་ཚོད་ག་ཅི་བསྒང་ལུ་ཡང་ ལོག་སྤོ་ཚུགས།','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) གི་ Babilim ཡིག་སྒྱུར་ལག་ལེན་འཐབ་མ་དགོ་ནི་ཨིན་ན། WordPress གིས་ དེ་གི་ཚབ་ཏུ་ པླགིན་དེ་རང་གི་ ཡང་ན་ WordPress.org ཡིག་སྒྱུར་ལག་ལེན་འཐབ་འོང་། ཁྱོད་ཀྱིས་ དུས་ཚོད་ག་ཅི་བསྒང་ལུ་ཡང་ ལོག་སྤོ་ཚུགས།']];